  ('scripture-2026-09-30', 'scripture', 'Psalm 31:5', 'Night Prayer (Compline)', '{"text":"Into your hand I commend my spirit.\nYou redeem me, Yahweh, God of truth.","option":"D","painting":{"artist":"Jean-François Millet","era":"Barbizon realism, 1857–59","title":"The Angelus"}}'::jsonb),
  ('scripture-2026-10-01', 'scripture', 'Genesis 28:16–17', 'Orthodox Vespers of the Protection', '{"text":"Jacob awakened out of his sleep, and he said, “Surely Yahweh is in this place, and I didn’t know it.” He was afraid, and said, “How awesome this place is! This is none other than God’s house, and this is the gate of heaven.”","option":"C","painting":{"artist":"William Blake","era":"English Romanticism, c. 1799–1806","title":"Jacob''s Ladder"}}'::jsonb),
  ('scripture-2026-10-02', 'scripture', 'Matthew 18:3–4, 10', 'Catholic Mass · Gospel (Guardian Angels)', '{"text":"Most certainly I tell you, unless you turn and become as little children, you will in no way enter into the Kingdom of Heaven. Whoever therefore humbles himself as this little child is the greatest in the Kingdom of Heaven. … See that you don''t despise one of these little ones, for I tell you that in heaven their angels always see the face of my Father who is in heaven.","option":"B","painting":{"artist":"Pietro da Cortona","era":"Italian Baroque, 1656","title":"The Guardian Angel"}}'::jsonb),
  ('scripture-2026-10-03', 'scripture', 'Acts 17:27–28a', 'Orthodox commemoration of St Dionysius the Areopagite', '{"text":"that they should seek the Lord, if perhaps they might reach out for him and find him, though he is not far from each one of us. ''For in him we live, move, and have our being.''","option":"C","painting":{"artist":"Raphael","era":"High Renaissance, 1515","title":"St Paul Preaching in Athens"}}'::jsonb),
  ('scripture-2026-10-04', 'scripture', 'Psalm 148:3, 7–10', 'Liturgy of the Hours · Sunday Morning Prayer (St Francis''s day)', '{"text":"Praise him, sun and moon! Praise him, all you shining stars! … Praise Yahweh from the earth, you great sea creatures, and all depths, lightning and hail, snow and clouds, stormy wind, fulfilling his word, mountains and all hills, fruit trees and all cedars, wild animals and all livestock, small creatures and flying birds,","option":"C","painting":{"artist":"Giotto (attributed)","era":"Proto-Renaissance, c. 1297–1300","title":"St Francis Preaching to the Birds"}}'::jsonb),
  ('scripture-2026-10-05', 'scripture', 'Luke 10:33–34', 'Catholic Mass · Gospel', '{"text":"But a certain Samaritan, as he traveled, came where he was. When he saw him, he was moved with compassion, came to him, and bound up his wounds, pouring on oil and wine. He set him on his own animal, brought him to an inn, and took care of him.","option":"B","painting":{"artist":"Eugène Delacroix","era":"French Romanticism, 1849","title":"The Good Samaritan"}}'::jsonb),
  ('scripture-2026-10-06', 'scripture', 'Luke 10:41–42', 'Catholic Mass · Gospel', '{"text":"Jesus answered her, \"Martha, Martha, you are anxious and troubled about many things, but one thing is needed. Mary has chosen the good part, which will not be taken away from her.\"","option":"B","painting":{"artist":"Diego Velázquez","era":"Spanish Golden Age, 1618","title":"Kitchen Scene with Christ in the House of Martha and Mary"}}'::jsonb),
  ('scripture-2026-10-07', 'scripture', 'Psalm 130:5–6', 'Night Prayer (Compline)', '{"text":"I wait for Yahweh. My soul waits. I hope in his word. My soul longs for the Lord more than watchmen long for the morning, more than watchmen for the morning.","option":"D","painting":{"artist":"Caspar David Friedrich","era":"German Romanticism, 1822","title":"Woman at a Window"}}'::jsonb),
  ('scripture-2026-10-08', 'scripture', 'Luke 11:9–10', 'Catholic Mass · Gospel', '{"text":"I tell you, keep asking, and it will be given you. Keep seeking, and you will find. Keep knocking, and it will be opened to you. For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.","option":"B","painting":{"artist":"William Holman Hunt","era":"Pre-Raphaelite, 1851–53","title":"The Light of the World"}}'::jsonb),
  ('scripture-2026-10-09', 'scripture', 'Philippians 2:3–4', 'Orthodox Divine Liturgy · Epistle', '{"text":"doing nothing through rivalry or through conceit, but in humility, each counting others better than himself; each of you not just looking to his own things, but each of you also to the things of others.","option":"B","painting":{"artist":"Ford Madox Brown","era":"Pre-Raphaelite, 1852–56","title":"Jesus Washing Peter''s Feet"}}'::jsonb)
